{"implementation":"def solve(case):
    items = case['items']
    required = set(case['required_failure_items'])
    unresolved_without = set(case['unresolved_without'])
    test_count = 0

    def test(subset):
        nonlocal test_count
        test_count += 1
        subset_set = set(subset)
        if not unresolved_without.issubset(subset_set):
            return 'UNRESOLVED'
        if required.issubset(subset_set):
            return 'FAIL'
        return 'PASS'

    # initial test must be FAIL per contract
    initial_result = test(items)
    if initial_result != 'FAIL':
        # if contract violated, still try to find any minimal failure
        pass

    def ddmin(current):
        n = 2
        while n <= len(current):
            # partition into n subsets
            subsets = []
            size = len(current) // n
            remainder = len(current) % n
            start = 0
            for i in range(n):
                end = start + size + (1 if i < remainder else 0)
                subsets.append(current[start:end])
                start = end
            reduced = False
            for subset in subsets:
                res = test(subset)
                if res == 'FAIL':
                    return ddmin(subset)
            for subset in subsets:
                complement = [x for x in current if x not in subset]
                res = test(complement)
                if res == 'FAIL':
                    return ddmin(complement)
            # no reduction, increase granularity
            n = min(2 * n, len(current))
        return current

    minimal = ddmin(items)
    return {
        'minimal_failure': minimal,
        'outcome': 'FAIL',
        'tests': test_count
    }"}
